import UIKit
import Capacitor

/// The one Capacitor bridge. A subclass only so the app's local plugin can be registered: `capacitor.config.json`'s
/// `packageClassList` is regenerated by `cap sync` from npm packages, so a plugin that lives in this target must be
/// registered by instance.
class CatchBridgeViewController: CAPBridgeViewController {
    override func capacitorDidLoad() {
        bridge?.registerPluginInstance(NativeTabBarPlugin())
    }
}
